const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {loadRuntime}=require('./headless-runtime.cjs');
const root=path.resolve(__dirname,'..'),legacy=JSON.parse(fs.readFileSync(path.join(__dirname,'fixtures/team-before-companion-skill-pools.json'),'utf8'));
// Fixture generated by the unmodified 1022772 runtime: two configured classes,
// a blank plan, a recruited companion, shared physical gems and allocated AP.
const json=(r,c)=>JSON.parse(r.run('JSON.stringify('+c+')'));
function expectedPlans(r){
 const counts=json(r,'CLASSES.map((c,j)=>({core:c.skills.length,support:SUPPORT[j].length}))');
 return legacy.buildSystem.plans.map(p=>{const out=structuredClone(p);if(p.job!==null)for(const [field,count,empty] of [['skills',counts[p.job].core,0],['supportLevels',counts[p.job].support,0],['sockets',counts[p.job].core,null]])out[field].push(...Array(count-out[field].length).fill(empty));return out;});
}
test('real pre-ownership saves append only empty skill positions and preserve all plans, allocations, gems and permanent records',()=>{
 const r=loadRuntime(root);r.ctx.legacy=structuredClone(legacy);const expected=expectedPlans(r),original=JSON.stringify(legacy);
 r.run('loadParty(legacy)');
 assert.deepEqual(json(r,'party.buildSystem.plans'),expected);assert.deepEqual(json(r,'party.buildSystem.permanent'),legacy.buildSystem.permanent);
 assert.deepEqual(json(r,'playerHero().gems'),legacy.members[0].gems);assert.deepEqual(json(r,'state.bag.map(g=>g.id)'),legacy.members.flatMap(h=>h.bag.map(g=>g.id)));
 assert.equal(r.run('JSON.stringify(legacy)'),original);assert.equal(r.run('partyMember(10).name'),legacy.members[1].name);
 for(const id of ['team-1','team-2','team-3','team-2']){r.ctx.id=id;r.run('switchTeamPlan(id);loadParty(packParty());');assert.deepEqual(json(r,'party.buildSystem.plans'),expected);}
 assert.deepEqual(r.errors,[]);
});
test('exact browser boot bytes reload safely and repeated import/save never grants points, skills or extra gem instances',()=>{
 const r=loadRuntime(root,'index.html',{'emberwild-save-v1':JSON.stringify(legacy)}),expected=expectedPlans(r);
 assert.equal(r.run('Boolean(party)'),true);assert.equal(r.run('globalThis.__EMBERWILD_BOOT_SAVE_ERROR??null'),null);assert.deepEqual(json(r,'party.buildSystem.plans'),expected);
 const before=json(r,'__EMBERWILD_TEAMS.budgets()'),gems=json(r,'playerHero().gems'),permanent=json(r,'party.buildSystem.permanent');
 r.run('for(let i=0;i<3;i++){loadParty(packParty());save();}');
 assert.deepEqual(json(r,'__EMBERWILD_TEAMS.budgets()'),before);assert.deepEqual(json(r,'playerHero().gems'),gems);assert.deepEqual(json(r,'party.buildSystem.permanent'),permanent);
 const cold=loadRuntime(root,'index.html',Object.fromEntries(r.values));assert.deepEqual(json(cold,'party.buildSystem.plans'),expected);assert.deepEqual(cold.errors,[]);assert(!cold.warnings.some(s=>s.includes('載入失敗')));
});
test('migration still rejects malformed, over-budget and out-of-range data before replacing the current party',()=>{
 const r=loadRuntime(root);r.run('start(0);closeModal();globalThis.liveParty=party;');const before=json(r,'packParty()');
 for(const edit of [d=>d.buildSystem.plans[0].stats[0]=999,d=>d.buildSystem.plans[0].skills[0]=2,d=>d.buildSystem.plans[0].skills=null,d=>d.buildSystem.plans[0].sockets[0]='gem-999',d=>d.buildSystem.plans[0].skills=Array(65).fill(0),d=>d.buildSystem.plans[0].active=[34,null]]){
  const bad=structuredClone(legacy);edit(bad);r.ctx.bad=bad;const original=JSON.stringify(bad);assert.throws(()=>r.run('loadParty(bad)'));assert.deepEqual(json(r,'packParty()'),before);assert(r.run('party===liveParty'));assert.equal(r.run('JSON.stringify(bad)'),original);
 }
});
